def check_control_files(pkg, params, ctx):
    import re
    files = sorted(pkg.files())
    if not files:
        pkg.fail('empty package')
        return
    groups = {}
    for f in files:
        if '/' not in f:
            pkg.fail('file outside a delivery folder')
            return
        folder = f.split('/', 1)[0]
        groups.setdefault(folder, []).append(f)
    pattern = re.compile(r'CONTROL_(\d+)\.txt')
    for folder in sorted(groups):
        members = groups[folder]
        controls = []
        for f in members:
            rest = f[len(folder) + 1:]
            if '/' in rest:
                continue
            m = pattern.fullmatch(rest)
            if m:
                controls.append(m)
        if len(controls) == 0:
            pkg.fail('no control file in ' + folder)
            return
        if len(controls) > 1:
            pkg.fail('more than one control file in ' + folder)
            return
        others = len(members) - 1
        if int(controls[0].group(1)) != others:
            pkg.fail('control count mismatch in ' + folder)
            return
